          if (remaining.length) return remaining[Math.min(index, remaining.length - 1)];
          return heading;
        }
      });
    });

    render();
    return { render: render };
  }

  initNav();

  window.UCR = {
    data: DATA,
    store: Store,
    findCourse: findCourse,
    deptName: deptName,
    seatsLeft: seatsLeft,
    availability: availability,
